// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    StaxLPStaking c;

    function setUp() public {
        c = new StaxLPStaking(address(this), address(this));
    }

    function _run(address caller) internal {
        vm.assume(caller != address(0));
        bool reverted;
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        bool amOwner = (owner == address(this));
        address newDistributor = caller;
        try c.setRewardDistributor(newDistributor) { reverted = false; } catch { reverted = true; }
        assertTrue(amOwner ? reverted == false : reverted == true);
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable {}
}
